```sparql
SELECT ?template_id ?template_type_code
WHERE {
  ?template a templates: ;
           templates:template_id ?template_id ;
           templates:ref-template_type_code ?template_type_code .
  ?document a documents: ;
            documents:ref-template ?template .
}
GROUP BY ?template_id ?template_type_code
