  FILTER (?degree_program1 IN (SELECT ?degree_program WHERE {
    ?degree_program rdf:type degree_programs ;
                   degree_summary_name "Masters"
  }))
  FILTER (?degree_program2 IN (SELECT ?degree_program WHERE {
    ?degree_program rdf:type degree_programs ;
                   degree_summary_name "Bachelors"
  }))
}
```

